mkdir -p /tmp/bot-check && cat > /tmp/bot-check/check.mjs <<'EOF'
import assert from "node:assert/strict";
import { decide } from "<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round6-heldout-c-haiku/work/courier-g2-2/bot.mjs";

const base = { userId: "u1", category: "marketing", timezone: "Europe/Istanbul", quietStart: "22:00", quietEnd: "07:30" };
const at = (iso) => new Date(iso);
let n = 0;
const ok = (name, fn) => { fn(); n++; console.log("ok -", name); };

// Istanbul is UTC+3, no DST. 2026-10-23.
ok("daytime marketing sends", () => {
  assert.deepEqual(decide({ ...base, userId: "a" }, at("2026-10-23T10:00:00Z")), { send: true, rule: null });
});
ok("quiet hours wrap past midnight: 23:30 local blocked", () => {
  assert.deepEqual(decide({ ...base, userId: "b" }, at("2026-10-23T20:30:00Z")), { send: false, rule: "quiet-hours" });
});
ok("quiet hours: 02:00 local blocked (after midnight)", () => {
  assert.deepEqual(decide({ ...base, userId: "b2" }, at("2026-10-23T23:00:00Z")), { send: false, rule: "quiet-hours" });
});
ok("quiet end is exclusive: 07:30 local sends", () => {
  assert.deepEqual(decide({ ...base, userId: "c" }, at("2026-10-23T04:30:00Z")), { send: true, rule: null });
});
ok("quiet start is inclusive: 22:00 local blocked", () => {
  assert.deepEqual(decide({ ...base, userId: "c2" }, at("2026-10-23T19:00:00Z")), { send: false, rule: "quiet-hours" });
});
ok("transactional passes during quiet hours", () => {
  assert.deepEqual(decide({ ...base, userId: "d", category: "transactional" }, at("2026-10-23T20:30:00Z")), { send: true, rule: null });
});
ok("blocked by quiet hours is not counted toward cap", () => {
  for (let i = 0; i < 5; i++) decide({ ...base, userId: "e" }, at("2026-10-23T20:30:00Z"));
  assert.deepEqual(decide({ ...base, userId: "e" }, at("2026-10-23T10:00:00Z")), { send: true, rule: null });
});
ok("daily cap: 3 sent, 4th blocked", () => {
  const t = at("2026-10-23T10:00:00Z");
  for (let i = 0; i < 3; i++) assert.equal(decide({ ...base, userId: "f" }, t).send, true);
  assert.deepEqual(decide({ ...base, userId: "f" }, t), { send: false, rule: "daily-cap" });
});
ok("transactional never blocked by cap and not counted", () => {
  const t = at("2026-10-23T10:00:00Z");
  for (let i = 0; i < 3; i++) decide({ ...base, userId: "g" }, t);
  assert.deepEqual(decide({ ...base, userId: "g", category: "transactional" }, t), { send: true, rule: null });
  assert.deepEqual(decide({ ...base, userId: "g" }, t), { send: false, rule: "daily-cap" });
});
ok("cap resets on the customer's local day, not UTC", () => {
  // 2026-10-23 21:30 UTC = 2026-10-24 00:30 Istanbul. Still quiet, use a zone where it's day.
  const z = { ...base, timezone: "America/New_York", quietStart: "00:00", quietEnd: "00:00", userId: "h" };
  // 2026-10-23 23:30 NY (= 03:30Z on 24th) and 2026-10-23 12:00 NY (= 16:00Z) are the same local day.
  for (let i = 0; i < 3; i++) decide(z, at("2026-10-24T03:30:00Z")); // local 10-23 23:30
  assert.deepEqual(decide(z, at("2026-10-23T16:00:00Z")), { send: false, rule: "daily-cap" }); // local 10-23 12:00
  // 2026-10-24 00:30 NY = 04:30Z 10-24 -> new local day
  assert.deepEqual(decide(z, at("2026-10-24T04:30:00Z")), { send: true, rule: null });
});
ok("same instant, different customers zones: independent", () => {
  const t = at("2026-10-23T10:00:00Z");
  const tokyo = { userId: "i", category: "marketing", timezone: "Asia/Tokyo", quietStart: "22:00", quietEnd: "07:00" };
  assert.deepEqual(decide(tokyo, t), { send: true, rule: null }); // 19:00 Tokyo, not quiet
});
ok("quiet window same-day (no wrap)", () => {
  const z = { userId: "j", category: "marketing", timezone: "UTC", quietStart: "13:00", quietEnd: "14:00" };
  assert.deepEqual(decide(z, at("2026-10-23T13:30:00Z")), { send: false, rule: "quiet-hours" });
  assert.deepEqual(decide(z, at("2026-10-23T14:00:00Z")), { send: true, rule: null });
});
ok("invalid input throws", () => {
  assert.throws(() => decide({ ...base, quietStart: "25:00" }, at("2026-10-23T10:00:00Z")), TypeError);
  assert.throws(() => decide({ ...base, category: "promo" }, at("2026-10-23T10:00:00Z")), TypeError);
  assert.throws(() => decide({ ...base, timezone: "Mars/Olympus" }, at("2026-10-23T10:00:00Z")), RangeError);
  assert.throws(() => decide(base, new Date("nope")), TypeError);
});
console.log(`\n${n} checks passed`);
EOF
cd /tmp/bot-check && node check.mjs
